pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function testFuzz_property(bytes memory data) public {
        Succeeder s = new Succeeder();
        bool ok = true;
        try c.forward(address(s), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Succeeder {
    fallback() external payable {}
    receive() external payable {}
}
